# Database backstops for the survey rules (the services refuse first):
# - once a survey leaves draft its questions, choices and settings are fixed;
# - responses only while open; an anonymous survey's response row may not
#   name the person or carry a time; answers must belong to the response's
#   survey and question.
SQL = """
CREATE OR REPLACE FUNCTION governance_survey_frozen() RETURNS trigger AS $$
BEGIN
    IF OLD.status <> 'draft' AND (
        NEW.status = 'draft'
        OR (OLD.status = 'closed' AND NEW.status <> 'closed')
        OR NEW.title IS DISTINCT FROM OLD.title
        OR NEW.intro IS DISTINCT FROM OLD.intro
        OR NEW.audience IS DISTINCT FROM OLD.audience
        OR NEW.opens_on IS DISTINCT FROM OLD.opens_on
        OR NEW.closes_on IS DISTINCT FROM OLD.closes_on
        OR NEW.anonymous IS DISTINCT FROM OLD.anonymous
    ) THEN
        RAISE EXCEPTION 'survey %: fixed once opened', OLD.id
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;
CREATE TRIGGER governance_survey_frozen BEFORE UPDATE ON governance_survey
    FOR EACH ROW EXECUTE FUNCTION governance_survey_frozen();

CREATE OR REPLACE FUNCTION governance_survey_question_frozen() RETURNS trigger AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM governance_survey s WHERE s.status <> 'draft' AND s.id IN (
            CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE NEW.survey_id END,
            CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.survey_id END)
    ) THEN
        RAISE EXCEPTION 'survey questions are fixed once the survey opens'
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;
CREATE TRIGGER governance_survey_question_frozen
    BEFORE INSERT OR UPDATE OR DELETE ON governance_surveyquestion
    FOR EACH ROW EXECUTE FUNCTION governance_survey_question_frozen();

CREATE OR REPLACE FUNCTION governance_survey_choice_frozen() RETURNS trigger AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM governance_surveyquestion q JOIN governance_survey s ON s.id = q.survey_id
        WHERE s.status <> 'draft' AND q.id IN (
            CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE NEW.question_id END,
            CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.question_id END)
    ) THEN
        RAISE EXCEPTION 'survey choices are fixed once the survey opens'
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;
CREATE TRIGGER governance_survey_choice_frozen
    BEFORE INSERT OR UPDATE OR DELETE ON governance_surveychoice
    FOR EACH ROW EXECUTE FUNCTION governance_survey_choice_frozen();

CREATE OR REPLACE FUNCTION governance_survey_open_guard() RETURNS trigger AS $$
BEGIN
    IF (SELECT status FROM governance_survey WHERE id = NEW.survey_id) IS DISTINCT FROM 'open' THEN
        RAISE EXCEPTION 'survey %: not open', NEW.survey_id
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;
CREATE TRIGGER governance_surveyparticipation_open BEFORE INSERT ON governance_surveyparticipation
    FOR EACH ROW EXECUTE FUNCTION governance_survey_open_guard();

CREATE OR REPLACE FUNCTION governance_survey_response_guard() RETURNS trigger AS $$
DECLARE anon boolean; st text;
BEGIN
    SELECT anonymous, status INTO anon, st FROM governance_survey WHERE id = NEW.survey_id;
    IF st IS DISTINCT FROM 'open' THEN
        RAISE EXCEPTION 'survey %: not open', NEW.survey_id
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF anon AND (NEW.person_id IS NOT NULL OR NEW.submitted_at IS NOT NULL) THEN
        RAISE EXCEPTION 'anonymous survey %: a response must not name the person or the time',
            NEW.survey_id USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF NOT anon AND NEW.person_id IS NULL THEN
        RAISE EXCEPTION 'named survey %: a response names the person', NEW.survey_id
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;
CREATE TRIGGER governance_surveyresponse_guard BEFORE INSERT ON governance_surveyresponse
    FOR EACH ROW EXECUTE FUNCTION governance_survey_response_guard();

CREATE OR REPLACE FUNCTION governance_survey_answer_guard() RETURNS trigger AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM governance_surveyresponse r JOIN governance_surveyquestion q
            ON q.survey_id = r.survey_id
        WHERE r.id = NEW.response_id AND q.id = NEW.question_id
    ) OR (NEW.choice_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM governance_surveychoice c
        WHERE c.id = NEW.choice_id AND c.question_id = NEW.question_id
    )) THEN
        RAISE EXCEPTION 'survey answer does not belong to its survey'
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;
CREATE TRIGGER governance_surveyanswer_guard BEFORE INSERT ON governance_surveyanswer
    FOR EACH ROW EXECUTE FUNCTION governance_survey_answer_guard();
"""

